#include <iomanip>
#include <iostream>
#include "mesh/cubed_sphere/hermite_boundary_probe.hpp"
#include "hermite_sampler_test_adapter.hpp"
#include "mesh/cubed_sphere/cross_face_boundary_probe.hpp"
namespace c=cubed_sphere;constexpr int fields=6;
std::array<c::Jet,fields> Exact(const Real*x){c::Jet X=c::Jet::Variable(x[0],0),Y=c::Jet::Variable(x[1],1),Z=c::Jet::Variable(x[2],2),R=c::Power(X*X+Y*Y+Z*Z,.5),nx=X/R,ny=Y/R,nz=Z/R,t=R-c::Jet(1),g=c::Jet(.3)*nx+c::Jet(.5)*ny*nz+c::Jet(.2)*nx*nx;return {c::Jet(3.14159),c::Jet(1)+c::Jet(.2)*nx+c::Jet(.3)*nx*ny+c::Jet(.4)*ny*nz+c::Jet(.1)*nx*nx*nx,t*g+t*t*(c::Jet(1)+c::Jet(.1)*nx*nz)+c::Jet(.1)*t*t*t*nz,X*Y+c::Jet(2)*Y*Z+c::Jet(3)*X*X*Z,t*g,t*t*g};}
struct Norm{Real first=0,second=0,mixed=0,value=0;std::array<Real,fields> field_first{},field_second{},field_mixed{};size_t count=0;void Add(const c::CenteredSurfaceAtlas::Jets&u,const std::array<c::Jet,fields>&e,const Real*x){++count;for(int f=1;f<fields;++f){value=std::max(value,std::abs(u.value[f]-e[f].f));for(int i=0;i<3;++i){first=std::max(first,std::abs(u.d[f][i]-e[f].d[i]));field_first[f]=std::max(field_first[f],std::abs(u.d[f][i]-e[f].d[i]));for(int j=0;j<3;++j){second=std::max(second,std::abs(u.dd[f][i][j]-e[f].h[i][j]));field_second[f]=std::max(field_second[f],std::abs(u.dd[f][i][j]-e[f].h[i][j]));}}for(int k=0;k<3;++k){Real m=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)m+=x[i]*(u.dd[f][i][j]-e[f].h[i][j])*((j==k?1.:0)-x[j]*x[k]);mixed=std::max(mixed,std::abs(m));field_mixed[f]=std::max(field_mixed[f],std::abs(m));}}}void Print()const{std::cout<<"{\"count\":"<<count<<",\"value_max\":"<<value<<",\"first_max\":"<<first<<",\"second_max\":"<<second<<",\"normal_tangent_hessian_max\":"<<mixed<<",\"fields\":[";for(int f=1;f<fields;++f){if(f>1)std::cout<<',';std::cout<<"{\"first\":"<<field_first[f]<<",\"second\":"<<field_second[f]<<",\"mixed\":"<<field_mixed[f]<<'}';}std::cout<<"]}";}};
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{if(argc<5)throw std::runtime_error("n shells subdivisions radial_nodes");int n=std::stoi(argv[1]),layers=std::stoi(argv[2]),sub=std::stoi(argv[3]),radial=std::stoi(argv[4]);std::vector<Real> radii=layers==1?std::vector<Real>{1}:layers==2?std::vector<Real>{.65,1}:std::vector<Real>{.45,.55,.60,.65,.70,.75,1};c::CompositeMesh mesh(.25,radii,sub,n,2);if(mesh.blocks.size()*size_t(n)*n*n>50000)throw std::runtime_error("bounded50000");c::CompositeDifference grid(mesh,4);c::ScriSurface surface(grid,fields,radial);std::vector<Real> volume(fields*grid.count,0),boundary(surface.values.size());for(size_t p=0;p<grid.active.size();++p){const auto e=Exact(grid.geometry[p].x);for(int f=0;f<fields;++f)volume[f*grid.count+grid.active[p]]=e[f].f;}for(size_t p=0;p<surface.rows.size();++p){const auto e=Exact(surface.rows[p].geometry.x);for(int f=0;f<fields;++f)boundary[p*fields+f]=e[f].f;boundary[p*fields+4]=boundary[p*fields+5]=0;}// Exact declared MMS traces, not an evolution reset.
 c::CrossFaceBoundaryProbe owner(surface,volume,boundary,fields);HermiteSamplerTestAdapter probe(surface,volume,boundary,fields);c::HermiteBoundaryProbe qualified_reference(surface,volume,boundary,fields);Norm all,edge,corner,seam,owner_all,owner_seam,oracle_all,oracle_seam;Real regression_max=0;bool regression_values_bitwise=true;Real constant=0,normal_difference=0,zero_trace_tangent=0,quadratic_normal=0,quadratic_mixed=0,zero_trace_surface_hessian=0;
 auto inspect=[&](int block,const Real*q,Norm&out,int which,bool actual,size_t point){const auto geometry=mesh.Geometry(block,q);auto u=which==1?probe.At(block,q):owner.At(block,q);out.Add(u,Exact(geometry.x),geometry.x);if(which!=1)return;const auto prior=qualified_reference.At(block,q);for(int f=0;f<fields;++f){regression_values_bitwise=regression_values_bitwise&&(u.value[f]==prior.value[f]);regression_max=std::max(regression_max,std::abs(u.value[f]-prior.value[f]));for(int i=0;i<3;++i){regression_max=std::max(regression_max,std::abs(u.d[f][i]-prior.d[f][i]));for(int j=0;j<3;++j)regression_max=std::max(regression_max,std::abs(u.dd[f][i][j]-prior.dd[f][i][j]));}}constant=std::max(constant,std::abs(u.value[0]-3.14159));for(int i=0;i<3;++i){constant=std::max(constant,std::abs(u.d[0][i]));for(int j=0;j<3;++j)constant=std::max(constant,std::abs(u.dd[0][i][j]));}Real G[2]{};for(int f=4;f<=5;++f)for(int i=0;i<3;++i)G[f-4]+=geometry.x[i]*u.d[f][i];quadratic_normal=std::max(quadratic_normal,std::abs(G[1]));for(int k=0;k<3;++k){for(int f=4;f<=5;++f){Real tangent=u.d[f][k]-geometry.x[k]*G[f-4];zero_trace_tangent=std::max(zero_trace_tangent,std::abs(tangent));}Real mixed=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)mixed+=geometry.x[i]*u.dd[5][i][j]*((j==k?1.:0)-geometry.x[j]*geometry.x[k]);quadratic_mixed=std::max(quadratic_mixed,std::abs(mixed));for(int j=0;j<3;++j){Real surface_hessian=0;for(int a=0;a<3;++a)for(int b=0;b<3;++b)surface_hessian+=((a==k?1.:0)-geometry.x[a]*geometry.x[k])*u.dd[4][a][b]*((b==j?1.:0)-geometry.x[b]*geometry.x[j]);surface_hessian-=G[0]*((k==j?1.:0)-geometry.x[k]*geometry.x[j]);zero_trace_surface_hessian=std::max(zero_trace_surface_hessian,std::abs(surface_hessian));}}
 if(actual){const auto old=surface.Sample(point,volume,boundary,fields);for(int f=0;f<fields;++f){Real d=0,dd=0;for(int i=0;i<3;++i){d+=geometry.x[i]*(u.d[f][i]-old.d[f][i]);for(int j=0;j<3;++j)dd+=geometry.x[i]*geometry.x[j]*(u.dd[f][i][j]-old.dd[f][i][j]);}normal_difference=std::max({normal_difference,std::abs(d),std::abs(dd)});}}};
 auto points=[&](int which){Norm &nodes=which==0?owner_all:which==1?all:oracle_all;Norm &seams=which==0?owner_seam:which==1?seam:oracle_seam;for(size_t p=0;p<surface.rows.size();++p){const auto &row=surface.rows[p];const Real q[3]={1,(row.j+.5)/n,(row.k+.5)/n};inspect(row.block,q,nodes,which,true,p);if(which==1){bool a=row.j<2||row.j>=n-2,b=row.k<2||row.k>=n-2;if(a||b)inspect(row.block,q,a&&b?corner:edge,which,false,0);}}for(size_t b=0;b<mesh.blocks.size();++b)if(surface.base[b]>=0)for(int j=0;j<=n;++j){Real q[3]={1,0,Real(j)/n};inspect(b,q,seams,which,false,0);q[1]=1;inspect(b,q,seams,which,false,0);q[1]=Real(j)/n;q[2]=0;inspect(b,q,seams,which,false,0);q[2]=1;inspect(b,q,seams,which,false,0);}};
 points(0);points(1);owner.exact_mms_query=[](const Real*x){auto u=Exact(x);std::vector<Real> v(fields);for(int f=0;f<fields;++f)v[f]=u[f].f;return v;};points(2);
 std::cout<<std::setprecision(17)<<"{\"method\":\"physical_normal_Hermite_boundary_atlas\",\"n\":"<<n<<",\"layers\":"<<layers<<",\"subdivisions\":"<<sub<<",\"radial_nodes\":"<<radial<<",\"cells\":"<<grid.active.size()<<",\"qualified_value_bitwise\":"<<regression_values_bitwise<<",\"qualified_full_jet_difference_max\":"<<regression_max<<",\"constant_max\":"<<constant<<",\"original_pure_normal_jet_difference_max\":"<<normal_difference<<",\"value_weight_l1_max\":"<<probe.diagnostics().value_weight_l1<<",\"angular_radial_factor_condition_indicator\":"<<probe.diagnostics().factor_condition_indicator<<",\"polynomial_reproduction_max\":"<<probe.diagnostics().polynomial_reproduction<<",\"zero_trace_tangent_gradient_max\":"<<zero_trace_tangent<<",\"zero_trace_intrinsic_hessian_max\":"<<zero_trace_surface_hessian<<",\"quadratic_trace_normal_max\":"<<quadratic_normal<<",\"quadratic_trace_mixed_max\":"<<quadratic_mixed<<",\"all_surface\":";all.Print();std::cout<<",\"edge_band\":";edge.Print();std::cout<<",\"corner_band\":";corner.Print();std::cout<<",\"exact_patch_seams_and_corners\":";seam.Print();std::cout<<",\"owner_all_surface\":";owner_all.Print();std::cout<<",\"owner_exact_seams\":";owner_seam.Print();std::cout<<",\"analytic_pullback_all_surface\":";oracle_all.Print();std::cout<<",\"analytic_pullback_exact_seams\":";oracle_seam.Print();std::cout<<"}\n";if(regression_max>1e-9||!regression_values_bitwise||constant>1e-13||normal_difference>1e-9||zero_trace_tangent>1e-12||zero_trace_surface_hessian>1e-10||quadratic_normal>1e-10||quadratic_mixed>1e-9||!std::isfinite(all.second+seam.second))throw std::runtime_error("Hermite boundary trace/normal/constant consistency failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
